1	package calibrate
2	
3	import (
4		"errors"
5		"path/filepath"
6		"testing"
7	)
8	
9	// 本文件为“器具登记信息返回结果”的既有行为提供自动化回归保障：
10	// 登记成功、按编号查询、列出器具与按器具核对返回的器具信息都是独立展示副本，
11	// 调用方对副本（编号、名称、允许误差、状态、登记时间）的整理不回写台账，
12	// 不释放或占用编号、不改变器具数量，也不影响使用资格判断与证书归属。
13	// 范围只涉及器具信息，不扩展到证书、使用原因或计划结果的副本测试。
14	
15	// 先按正式登记信息断言一件器具，测试辅助。
16	func assertOfficialInstrument(t *testing.T, l *Ledger, id, name string, allowed float64, status Status, registeredAt string) {
17		t.Helper()
18		got, err := l.Instrument(id)
19		if err != nil {
20			t.Fatalf("按原编号 %s 查询应仍存在：%v", id, err)
21		}
22		if got.ID != id || got.Name != name || got.AllowedError != allowed ||
23			got.Status != status || got.RegisteredAt != registeredAt {
24			t.Fatalf("正式登记信息与保存内容不符：%+v", got)
25		}
26	}
