28	// TestReturnedRegisterResultCannotRewriteLedger 对应核心场景：登记成功返回的
29	// 器具副本被全面整理（改编号、名称、允许误差、状态、登记时间）后，按原编号
30	// 查询、列出器具与核对仍得到实际保存的登记信息；原编号不释放、新编号不占用、
31	// 器具数量不增加；随后一次正常写盘也不把展示内容带入台账文件。
32	func TestReturnedRegisterResultCannotRewriteLedger(t *testing.T) {
33		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
34		path := filepath.Join(t.TempDir(), "ledger.json")
35		l, err := openAt(path, clock.now)
36		if err != nil {
37			t.Fatalf("open: %v", err)
38		}
39		mustRegister(t, l, "M-2", "示波器", 1.0)
40	
41		registered, err := l.Register(RegisterInput{ID: "M-1", Name: " 万用表 ", AllowedError: 0.5})
42		if err != nil {
43			t.Fatalf("register: %v", err)
44		}
45		if registered.ID != "M-1" || registered.Name != "万用表" ||
46			registered.AllowedError != 0.5 || registered.Status != StatusPending {
47			t.Fatalf("登记返回结果内容异常：%+v", registered)
48		}
49		savedAt := registered.RegisteredAt
50		if savedAt == "" {
51			t.Fatal("登记时间不应为空")
52		}
53	
54		// 调用方整理返回结果：编号改成尚不存在的编号，并改动全部其他字段。
55		registered.ID = "M-NEW"
56		registered.Name = "展示用名称"
57		registered.AllowedError = 9.9
58		registered.Status = StatusInUse
59		registered.RegisteredAt = "2099-01-01T00:00:00Z"
60	
61		// 原器具没有消失，查询、列出、核对都仍是实际保存的登记信息。
62		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusPending, savedAt)
63		list := l.Instruments()
64		if len(list) != 2 {
65			t.Fatalf("正式器具数量应保持 2 件，得到 %d 件：%+v", len(list), list)
66		}
67		var listed *Instrument
68		for i := range list {
69			if list[i].ID == "M-1" {
70				listed = &list[i]
71			}
72		}
73		if listed == nil || listed.Name != "万用表" || listed.AllowedError != 0.5 ||
74			listed.Status != StatusPending || listed.RegisteredAt != savedAt {
75			t.Fatalf("列出器具被返回结果改写：%+v", list)
76		}
77		r, err := l.Review("M-1")
78		if err != nil {
79			t.Fatalf("review: %v", err)
80		}
81		if r.Instrument.ID != "M-1" || r.Instrument.Name != "万用表" ||
82			r.Instrument.AllowedError != 0.5 || r.Instrument.Status != StatusPending ||
83			r.Instrument.RegisteredAt != savedAt {
84			t.Fatalf("核对中的登记信息被返回结果改写：%+v", r.Instrument)
85		}
86	
87		// 原编号未释放：再登记原编号仍被拒绝；副本中的新编号不存在、未占用。
88		if _, err := l.Register(RegisterInput{ID: "M-1", Name: "另一件", AllowedError: 0.1}); !IsValidation(err) {
89			t.Fatalf("原编号仍应占用、重复登记被拒绝，得到 %v", err)
90		}
91		if _, err := l.Instrument("M-NEW"); err == nil {
92			t.Fatal("只在副本中出现的新编号不应能查到")
93		} else if !errors.Is(err, ErrNotFound) {
94			t.Fatalf("新编号查询应报告不存在，得到 %v", err)
95		}
96		// 新编号未被占用：用它登记应成功，台账变为 3 件，原器具仍在。
97		mustRegister(t, l, "M-NEW", "真新器具", 0.2)
98		if len(l.Instruments()) != 3 {
99			t.Fatalf("副本改写未新增器具，正式登记 M-NEW 后应为 3 件，得到 %d 件", len(l.Instruments()))
100		}
101		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusPending, savedAt)
102	
103		// 正常状态切换保存后重开同一台账，读到的仍是正式登记信息与真实状态。
104		if err := l.SetStatus("M-1", StatusRetired); err != nil {
105			t.Fatalf("set status: %v", err)
106		}
107		reopened, err := openAt(path, clock.now)
108		if err != nil {
109			t.Fatalf("reopen: %v", err)
110		}
111		if len(reopened.Instruments()) != 3 {
112			t.Fatalf("重开后器具数量应为 3，得到 %d", len(reopened.Instruments()))
113		}
114		got, err := reopened.Instrument("M-1")
115		if err != nil {
116			t.Fatalf("reopen instrument: %v", err)
117		}
118		if got.Name != "万用表" || got.AllowedError != 0.5 || got.Status != StatusRetired ||
119			got.RegisteredAt != savedAt {
120			t.Fatalf("展示内容被写盘带入台账：%+v", got)
121		}
122	}
