124	// TestReturnedInstrumentMutationCannotRaiseLimitOrLiftRetirement 验证器具信息
125	// 副本对使用资格判断没有影响：
126	//   - 在用器具证书未到期但测得误差超过登记限值时，把副本允许误差调大，
127	//     核对仍显示超差、申请使用仍被拒绝，原因仍按正式限值说明；
128	//   - 停用器具即使有合格且未到期的证书，把副本状态改成在用也不能解除停用；
129	//   - 原本允许使用的器具，不会因为副本被调低限值或改成停用而失去资格。
130	func TestReturnedInstrumentMutationCannotRaiseLimitOrLiftRetirement(t *testing.T) {
131		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
132		l := newTestLedger(t, clock)
133	
134		// M-1：在用，登记限值 0.5；证书测得 0.8，未到期——正式数据为超差。
135		mustRegister(t, l, "M-1", "万用表", 0.5)
136		_ = l.SetStatus("M-1", StatusInUse)
137		mustAddCert(t, l, CertificateInput{
138			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
139			Expiry: "2027-09-01", Method: "m", Error: 0.8, Summary: "超差批次",
140		})
141		over, err := l.Instrument("M-1")
142		if err != nil {
143			t.Fatalf("instrument: %v", err)
144		}
145		over.AllowedError = 100
146	
147		// 分别从按编号查询、列出与核对三个入口取得副本并调大限值。
148		if list := l.Instruments(); len(list) != 1 {
149			t.Fatalf("应只有一件器具，得到 %d", len(list))
150		} else {
151			list[0].AllowedError = 100
152		}
153		rv, err := l.Review("M-1")
154		if err != nil {
155			t.Fatalf("review: %v", err)
156		}
157		rv.Instrument.AllowedError = 100
158		if rv.Latest == nil || rv.Latest.Pass {
159			t.Fatalf("核对仍应按正式限值判定超差，得到 %+v", rv.Latest)
160		}
161		if rv.CanUse || !containsReason(rv.Reasons, "超差") ||
162			!containsReason(rv.Reasons, "0.5") {
163			t.Fatalf("调大副本限值不应解除超差限制，原因应按正式限值 0.5 说明，得到 %v", rv.Reasons)
164		}
165		d, err := l.CanUse("M-1")
166		if err != nil || d.Allowed {
167			t.Fatalf("调大副本限值后申请使用仍应被拒绝，err=%v allowed=%v", err, d.Allowed)
168		}
169		if !containsReason(d.Reasons, "超差") || !containsReason(d.Reasons, "0.5") {
170			t.Fatalf("拒绝原因应仍按正式限值说明，得到 %v", d.Reasons)
171		}
172		d2, err := l.RequestUse("M-1")
173		if err != nil || d2.Allowed {
174			t.Fatalf("申请使用应被拒绝并留痕，err=%v allowed=%v", err, d2.Allowed)
175		}
176		if !containsReason(d2.Reasons, "超差") {
177			t.Fatalf("留痕的拒绝原因应按正式限值显示超差，得到 %v", d2.Reasons)
178		}
179	
180		// M-2：停用，但有合格且未到期的证书——正式数据为停用限制。
181		mustRegister(t, l, "M-2", "温度计", 0.5)
182		mustAddCert(t, l, CertificateInput{
183			InstrumentID: "M-2", Number: "C-2", CalDate: "2026-09-01",
184			Expiry: "2027-09-01", Method: "m", Error: 0.1, Summary: "合格",
185		})
186		if err := l.SetStatus("M-2", StatusRetired); err != nil {
187			t.Fatalf("retire M-2: %v", err)
188		}
189		retired, err := l.Instrument("M-2")
190		if err != nil {
191			t.Fatalf("instrument M-2: %v", err)
192		}
193		retired.Status = StatusInUse
194		rv2, _ := l.Review("M-2")
195		rv2.Instrument.Status = StatusInUse
196		if rv2.CanUse || !containsReason(rv2.Reasons, "停用") {
197			t.Fatalf("把副本状态改成在用不应解除停用限制，得到 canUse=%v reasons=%v",
198				rv2.CanUse, rv2.Reasons)
199		}
200		d3, err := l.RequestUse("M-2")
201		if err != nil || d3.Allowed || !containsReason(d3.Reasons, "停用") {
202			t.Fatalf("停用器具申请使用仍应被拒绝且原因含停用，err=%v decision=%+v", err, d3)
203		}
204	
205		// M-3：在用、证书合格且未到期——正式数据允许使用；调低副本限值或改成
206		// 停用都不能让它失去资格。
207		mustRegister(t, l, "M-3", "压力表", 1.0)
208		_ = l.SetStatus("M-3", StatusInUse)
209		mustAddCert(t, l, CertificateInput{
210			InstrumentID: "M-3", Number: "C-3", CalDate: "2026-09-01",
211			Expiry: "2027-09-01", Method: "m", Error: 0.8, Summary: "合格",
212		})
213		ok, err := l.Instrument("M-3")
214		if err != nil {
215			t.Fatalf("instrument M-3: %v", err)
216		}
217		ok.AllowedError = 0 // 正式限值 1.0 下 0.8 合格，副本限值 0 下应为超差。
218		ok.Status = StatusRetired
219		rv3, _ := l.Review("M-3")
220		rv3.Instrument.AllowedError = 0
221		rv3.Instrument.Status = StatusRetired
222		if !rv3.CanUse || rv3.Latest == nil || !rv3.Latest.Pass {
223			t.Fatalf("原本允许使用的器具不应因副本整理失去资格：canUse=%v latest=%+v",
224				rv3.CanUse, rv3.Latest)
225		}
226		d4, err := l.RequestUse("M-3")
227		if err != nil || !d4.Allowed {
228			t.Fatalf("正式合格在用的器具申请应获准，err=%v decision=%+v", err, d4)
229		}
230	
231		// 证书内容与归属不因这些整理改变。
232		for _, want := range []struct {
233			id, number string
234			errV       float64
235		}{
236			{"M-1", "C-1", 0.8},
237			{"M-2", "C-2", 0.1},
238			{"M-3", "C-3", 0.8},
239		} {
240			c := l.LatestCertificate(want.id)
241			if c == nil || c.Number != want.number || c.Error != want.errV ||
242				c.InstrumentID != want.id {
243				t.Fatalf("证书内容或归属被器具副本整理改变：%+v", c)
244			}
245		}
246		// 正式登记的允许误差与状态保持原值。
247		assertOfficialInstrument(t, l, "M-1", "万用表", 0.5, StatusInUse, l.findInstrument("M-1").RegisteredAt)
248		assertOfficialInstrument(t, l, "M-2", "温度计", 0.5, StatusRetired, l.findInstrument("M-2").RegisteredAt)
249		assertOfficialInstrument(t, l, "M-3", "压力表", 1.0, StatusInUse, l.findInstrument("M-3").RegisteredAt)
250	}
