366	// TestRealStatusChangeUpdatesNewQueriesButFetchedCopiesStayFrozen 验证正式状态
367	// 切换成功后，新查询显示真实的新状态，而此前取得的器具副本仍保留获取时的
368	// 内容；展示数据的修改不随这次正常保存进入台账文件。
369	func TestRealStatusChangeUpdatesNewQueriesButFetchedCopiesStayFrozen(t *testing.T) {
370		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
371		path := filepath.Join(t.TempDir(), "ledger.json")
372		l, err := openAt(path, clock.now)
373		if err != nil {
374			t.Fatalf("open: %v", err)
375		}
376		mustRegister(t, l, "M-1", "万用表", 0.5)
377		mustRegister(t, l, "M-2", "温度计", 0.2)
378		if err := l.SetStatus("M-1", StatusInUse); err != nil {
379			t.Fatalf("set M-1 in-use: %v", err)
380		}
381		if err := l.SetStatus("M-2", StatusInUse); err != nil {
382			t.Fatalf("set M-2 in-use: %v", err)
383		}
384	
385		// 在正式切换为停用之前取得各入口的副本（此时两件器具都在用）。
386		beforeQ, _ := l.Instrument("M-1")
387		beforeList := l.Instruments()
388		beforeReview, _ := l.Review("M-1")
389		beforeRegistered, _ := l.Register(RegisterInput{ID: "M-3", Name: "压力表", AllowedError: 1.0})
390	
391		// 调用方先在副本上做展示整理，再执行正式状态切换。
392		beforeQ.AllowedError = 9
393		beforeList[0].Name = "列表展示名"
394		beforeReview.Instrument.AllowedError = 8
395		beforeRegistered.Status = StatusInUse // M-3 正式为待校准，副本伪造成在用
396	
397		// 通过正常状态切换功能把 M-1、M-2 正式改为停用（正常写盘）。
398		if err := l.SetStatus("M-1", StatusRetired); err != nil {
399			t.Fatalf("set M-1 retired: %v", err)
400		}
401		if err := l.SetStatus("M-2", StatusRetired); err != nil {
402			t.Fatalf("set M-2 retired: %v", err)
403		}
404	
405		// 新查询显示真实的新状态与正式限值/名称。
406		afterQ, err := l.Instrument("M-1")
407		if err != nil {
408			t.Fatalf("instrument after: %v", err)
409		}
410		if afterQ.Status != StatusRetired || afterQ.AllowedError != 0.5 || afterQ.Name != "万用表" {
411			t.Fatalf("正式切换后新查询应显示真实状态与登记信息：%+v", afterQ)
412		}
413		afterList := l.Instruments()
414		var afterListed *Instrument
415		for i := range afterList {
416			if afterList[i].ID == "M-1" {
417				afterListed = &afterList[i]
418			}
419		}
420		if afterListed == nil || afterListed.Status != StatusRetired || afterListed.Name != "万用表" {
421			t.Fatalf("正式切换后列出结果应显示新状态与正式名称：%+v", afterList)
422		}
423		afterReview, _ := l.Review("M-1")
424		if afterReview.Instrument.Status != StatusRetired ||
425			afterReview.CanUse || !containsReason(afterReview.Reasons, "停用") {
426			t.Fatalf("正式停用后核对应显示停用并拒绝使用：%+v", afterReview)
427		}
428		// M-3 未经正式切换仍为待校准，副本伪造成在用不影响它，也不影响 M-2。
429		if got, _ := l.Instrument("M-3"); got.Status != StatusPending {
430			t.Fatalf("M-3 应仍为待校准，得到 %+v", got)
431		}
432		if got, _ := l.Instrument("M-2"); got.Status != StatusRetired {
433			t.Fatalf("M-2 新查询应显示停用，得到 %+v", got)
434		}
435	
436		// 此前取得的副本保留获取时的内容与调用方自己的整理，不随正式变化更新。
437		if beforeQ.Status != StatusInUse || beforeQ.AllowedError != 9 || beforeQ.Name != "万用表" {
438			t.Fatalf("旧查询副本应保留获取时的在用状态与自身整理：%+v", beforeQ)
439		}
440		var oldListed *Instrument
441		for i := range beforeList {
442			if beforeList[i].ID == "M-1" {
443				oldListed = &beforeList[i]
444			}
445		}
446		if oldListed == nil || oldListed.Status != StatusInUse || oldListed.Name != "列表展示名" {
447			t.Fatalf("旧列表副本应保留获取时状态与自身整理：%+v", beforeList)
448		}
449		if beforeReview.Instrument.Status != StatusInUse || beforeReview.Instrument.AllowedError != 8 {
450			t.Fatalf("旧核对副本应保留获取时的在用状态与自身整理：%+v", beforeReview.Instrument)
451		}
452		if beforeRegistered.Status != StatusInUse {
453			t.Fatalf("登记返回副本被后续正式状态切换带动变化：%+v", beforeRegistered)
454		}
455	
456		// 重新打开同一台账：正式登记信息与真实状态保留，展示数据未进入文件。
457		reopened, err := openAt(path, clock.now)
458		if err != nil {
459			t.Fatalf("reopen: %v", err)
460		}
461		g1, _ := reopened.Instrument("M-1")
462		if g1.Name != "万用表" || g1.AllowedError != 0.5 || g1.Status != StatusRetired {
463			t.Fatalf("重开后 M-1 应为正式内容与停用状态：%+v", g1)
464		}
465		g2, _ := reopened.Instrument("M-2")
466		if g2.Name != "温度计" || g2.AllowedError != 0.2 || g2.Status != StatusRetired {
467			t.Fatalf("重开后 M-2 应为正式内容与真实状态：%+v", g2)
468		}
469		g3, _ := reopened.Instrument("M-3")
470		if g3.Name != "压力表" || g3.AllowedError != 1.0 || g3.Status != StatusPending {
471			t.Fatalf("重开后 M-3 应为正式内容与待校准状态：%+v", g3)
472		}
473		if len(reopened.Instruments()) != 3 {
474			t.Fatalf("重开后正式器具数量应为 3，得到 %d", len(reopened.Instruments()))
475		}
476	}
